const staticData = $getWorkflowStaticData('global');
staticData.chats = staticData.chats || {};

const item = $input.all()[0].json;
const chatId = item.message.chat.id;
const text = item.message.text || '';

if (text.toLowerCase() === '/start' || text.toLowerCase() === 'reiniciar') {
  staticData.chats[chatId] = [];
}

if (!staticData.chats[chatId] || staticData.chats[chatId].length === 0) {
  const systemPrompt = `Eres Fisioterapeuta Li, un asistente inteligente corporativo por Telegram.
Tu objetivo es ayudar a gestionar el negocio. Eres capaz de:
1. Agendar citas (agendar_cita). Pide nombre, fecha (YYYY-MM-DD), hora (HH:MM) y servicio.
2. Consultar la agenda del día (consultar_agenda).
3. Crear carpetas en Google Drive (crear_carpeta). Pide el nombre de la carpeta.
4. Buscar archivos en Google Drive (buscar_archivo). Pide el nombre del archivo.
5. Guardar reportes o notas en Google Sheets (guardar_reporte). Pide el texto de la nota.

RESPONDE ÚNICAMENTE CON UN JSON VÁLIDO en este formato:
{
  "estado": "conversar" | "agendar_cita" | "consultar_agenda" | "crear_carpeta" | "buscar_archivo" | "guardar_reporte",
  "mensaje_usuario": "Lo que le dices al usuario en Telegram. Por ejemplo, confirmaciones o pedir datos faltantes.",
  "datos": {
    "nombre": "",
    "fecha": "",
    "hora": "",
    "servicio": "",
    "nombre_carpeta": "",
    "nombre_archivo": "",
    "texto_reporte": ""
  }
}

REGLAS DE ESTADO:
- 'conversar': Usa esto si el usuario te saluda, te hace una pregunta general, o si te faltan datos para ejecutar una de las otras acciones. Pide amablemente los datos faltantes.
- 'agendar_cita': USA ESTO SOLO SI el usuario explícitamente confirmó que quiere reservar Y ya tienes nombre, fecha, hora y servicio.
- 'consultar_agenda': Usa esto si el usuario quiere saber las citas o la agenda de hoy.
- 'crear_carpeta': Usa esto si el usuario te pidió crear una carpeta Y ya tienes el nombre de la carpeta.
- 'buscar_archivo': Usa esto si el usuario quiere buscar un documento Y ya te dijo el nombre.
- 'guardar_reporte': Usa esto si el usuario te pide registrar algo en el sistema/sábana Y ya tienes el texto.

REGLAS DE DATOS:
- Mantén siempre en el JSON los datos que ya hayas recolectado en el historial.`;

  staticData.chats[chatId] = [{ role: 'system', content: systemPrompt }];
}

if (staticData.chats[chatId].length > 15) {
  staticData.chats[chatId] = [staticData.chats[chatId][0], ...staticData.chats[chatId].slice(-14)];
}

staticData.chats[chatId].push({ role: 'user', content: text });

return [{ json: { chatId: chatId, messages: staticData.chats[chatId] } }];

const staticData = $getWorkflowStaticData('global');
const item = $input.all()[0].json;
const chatId = $('Preparar Memoria (StaticData)').first().json.chatId;
const responseText = item.message.content;

if (staticData.chats && staticData.chats[chatId]) {
  staticData.chats[chatId].push({ role: 'assistant', content: responseText });
}

let parsed;
try {
  let cleanText = responseText.replace(/^```json\n?/i, '').replace(/```$/,'').trim();
  parsed = JSON.parse(cleanText);
} catch(e) {
  parsed = {
    estado: 'conversar',
    mensaje_usuario: 'Tuve un pequeño problema técnico procesando tu mensaje. ¿Me lo repites por favor?',
    datos: {}
  };
}

return [{ json: {
  chatId: chatId,
  estado: parsed.estado || 'conversar',
  mensaje_usuario: parsed.mensaje_usuario || 'Procesado.',
  datos: parsed.datos || {}
}}];

