const item = $input.all()[0].json;
const chatId = $node['Guardar Respuesta en Memoria'].json.chatId;
const datos = $node['Guardar Respuesta en Memoria'].json.datos;

let errorMsg = item.error || 'Error desconocido';
let slotsDisponibles = item.slots_disponibles || [];
let mensaje = '';

if (errorMsg.includes('no disponible') || errorMsg.includes('Horario no disponible') || item.disponible === false) {
  mensaje = `😔 Lo siento, el horario de las ${datos.hora} del ${datos.fecha} ya no está disponible.`;
  if (slotsDisponibles.length > 0) {
    const primeros = slotsDisponibles.slice(0, 5).map(s => s.substring(11, 16));
    mensaje += `\n\n📋 Horarios libres ese día:\n${primeros.map(h => '  🕐 ' + h).join('\n')}`;
    mensaje += '\n\n¿Te gustaría alguno de estos horarios?';
  } else {
    mensaje += '\n\nNo hay horarios disponibles para ese día. ¿Quieres intentar con otra fecha?';
  }
} else if (errorMsg.includes('fecha') && (errorMsg.includes('pasad') || errorMsg.includes('inválid'))) {
  mensaje = `📅 La fecha ${datos.fecha} no es válida o ya pasó. Por favor, indícame una fecha futura.`;
} else if (errorMsg.includes('servicio') || errorMsg.includes('no encontrad')) {
  mensaje = `🔍 No encontré el servicio "${datos.servicio}". Nuestros servicios son:\n  • Terapia Manual\n  • Rehabilitación Postquirúrgica\n  • Terapia Deportiva\n  • Masaje Terapéutico\n  • Evaluación Inicial\n  • Electroterapia\n\n¿Cuál te interesa?`;
} else {
  mensaje = `⚠️ Hubo un problemita al guardar tu cita: ${errorMsg}\n\n¿Quieres intentar de nuevo?`;
}

// Reset the conversation state so user can try again
const staticData = $getWorkflowStaticData('global');
if (staticData.chats && staticData.chats[chatId]) {
  // Remove the last assistant message that said "Procesando tu reserva..."
  const history = staticData.chats[chatId];
  if (history.length > 0 && history[history.length - 1].role === 'assistant') {
    history.pop();
  }
}

return [{ json: { chatId, mensaje } }];

